create or replace TABLE KFL_PRODUCTION.DBP_DATA.WUPCAL_2 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'PK Mandant_2 im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'PK Warenumschlagsplatz',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'PK - Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	DAT DATE NOT NULL COMMENT 'PK - Datum im Format JJJJ-MM_2-TT',
	OFFEN NUMBER(38,0) COMMENT 'kennzeichnet, ob ein Markt zu einem Datum geoeffnet war. 1 offen, 0 geschlossen',
	WERBEWOCHE NUMBER(38,0) COMMENT 'wird z.Zt. nicht benutzt',
	DATENLIEFERUNG_ARTBEW_WG_SUM NUMBER(38,0) COMMENT 'Datenlieferungs-Stati\t\n            0\tnicht geliefert\n            1\tgeliefert\n            2\tkalkuliert\n            3\tgesplittet\n            4\tnicht mehr lieferbar\n            5\tkumuliert (ueber n Tage)\n            6\tkalkuliert und nicht mehr lieferbar',
	DATENLIEFERUNG_BONANZAHL NUMBER(38,0) COMMENT 'Datenlieferungs-Stati\t\n            0\tnicht geliefert\n            1\tgeliefert\n            2\tkalkuliert\n            3\tgesplittet\n            4\tnicht mehr lieferbar\n            5\tkumuliert (ueber n Tage)\n            6\tkalkuliert und nicht mehr lieferbar',
	DATENLIEFERUNG_MISVIER NUMBER(38,0) COMMENT 'Daten aus der Schnittstelle misvier wurden geliefert\n            Datenlieferungs-Stati\t\n            0\tnicht geliefert\n            1\tgeliefert\n            2\tkalkuliert\n            3\tgesplittet\n            4\tnicht mehr lieferbar\n            5\tkumuliert (ueber n Tage)\n            6\tkalkuliert und nicht mehr lieferbar',
	DATENLIEFERUNG_ARTBEW NUMBER(38,0) COMMENT 'Lieferung der Artikelbewegungsdaten aus dem Markt\n            Datenlieferungs-Stati\t\n            0\tnicht geliefert\n            1\tgeliefert\n            2\tkalkuliert\n            3\tgesplittet\n            4\tnicht mehr lieferbar\n            5\tkumuliert (ueber n Tage)\n            6\tkalkuliert und nicht mehr lieferbar',
	DATENLIEFERUNG_QBM_STATUS NUMBER(38,0) COMMENT 'Lieferung der QBM-Daten (Reklamationen) aus dem Markt\n            Datenlieferungs-Stati\t\n            0   nicht geliefert\n            1    geliefert\n            weitere Stati koennen zu einem spaeteren Zeitpunkt festgelegt werden',
	PRUEF_STATUS_ID_UMSATZ NUMBER(38,0) COMMENT 'Status_2 der Pruefung des Umsatzes. Der Umsatz wird auf Plausibilitaet geprueft',
	PRUEF_STATUS_ID_KUNDE NUMBER(38,0) COMMENT 'Status_2 der Pruefung der Kundenzahl. Die Kundenzahl wird auf Plausibilitaet geprueft',
	PRUEF_GRUND_ID_UMSATZ VARCHAR(3) COLLATE 'en-ci' COMMENT 'Grund der Pruefung des Umsatzes',
	PRUEF_GRUND_ID_KUNDE VARCHAR(3) COLLATE 'en-ci' COMMENT 'Grund der Pruefung der Kundenzahl',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Waehrung, z.Bsp. CZK, EUR',
	DAT_EXTRAKT_UMSATZ DATE COMMENT 'Datum des Erhalts der  Schnittstelle Umsatz',
	OFFEN_VON NUMBER(38,0) COMMENT 'Zeitpunkt der Marktoeffnung',
	OFFEN_BIS NUMBER(38,0) COMMENT 'Schließungszeitpunkt des Marktes',
	OFFEN_THEKE_VON TIME(0) COMMENT 'Thekenoeffnungszeit von pro Markt / Tag_2',
	OFFEN_THEKE_BIS TIME(0) COMMENT 'Thekenoeffnungszeit bis pro Markt / Tag_2',
	UMSATZ_BRUTTO_ODS_VERKAUF NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Befuellung im ETL-Prozess - Summe Umsaetze aus ods_verkauf. Nur K-POS',
	UMSATZ_BRUTTO_ODS_KASSENABSCHLUSS NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Befuellung im ETL-Prozess - Summe Umsaetze aus ods_kassenabschluss. Nur K_POS',
	BONANZAHL NUMBER(38,0) COMMENT 'Anzahl der Kassenbons',
	BONANZAHL_MISVIER NUMBER(38,0) COMMENT 'Anzahl Bons',
	BONANZAHL_IMBISS NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Kunden im Imbiss des Marktes. Gehoert logisch nicht hierher, da abhaengig von einer Warengruppe bzw. bestimmten Kassierer-Nummern.',
	BONANZAHL_SUG NUMBER(38,0) COMMENT 'Bons mit mindestens einer positiven Position - einheitliche Definition der Kundenzahl innerhalb der Schwarz-Unternehmensgruppe',
	BONANZAHL_SUG_KASSENABSCHLUSS NUMBER(38,0) COMMENT 'Kunden Kassenabschluss (EOD), Logik analog bonanzahl_sug',
	BONANZAHL_FRISCHETHEKE_OHNE_FISCH NUMBER(38,0) COMMENT 'Kundenanzahl der Frischetheke ohne OWG 1005 Fisch (Sobald ein Kunde etwas aus den OWGs 1001, 1002, 1003, 1004 kauft, zählt dieser als Kunde der Frischetheke ohne Fisch).',
	BONANZAHL_KUNDENKARTE_PAYBACK NUMBER(38,0) COMMENT 'Anzahl der Kunden mit Payback als Kundenkarte (nur für Polen).',
	BONANZAHL_KUNDENKARTE NUMBER(38,0) COMMENT 'Aggregation der Bons mit Kundenkarten_Typ_ID = 2 (Kaufland Loyalty Card) auf Markt-Tag_2-Land_2-Ebene ',
	BETRAG_VK_NETTO_KUNDENKARTE NUMBER(38,4) COMMENT 'Umsatz netto mit Kaufland Loyalty Programm (kundenkarte_typ_id =2) auf Markt.Tag_2-Ebene.',
	SSM_UMSATZ_FAKTOR NUMBER(18,10) NOT NULL DEFAULT 1 COMMENT 'Berechnung je Wochentag. HL_2 Planwert / Durchschnitt letzte 10 Wochen',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_WUPCAL primary key (MANDANT_ID, WUP_ID, NB_ID, DAT)
)COMMENT='TP1 TP2 Marktkalender.'
;